<script lang="ts">
import {Component} from 'vue-property-decorator'
import LeftPanel from './LeftPanel.vue'
import {PortalPageView, TopBarNavigationTarget, TopBarView} from '@/view/View'
import {PortalVueBase} from '@/view/PortalVueBase'
import ToolbarTitle from '@/view/ToolbarTitle.vue'
import LanguagePicker from '@/view/LanguagePicker.vue'
import BrandLogo from '@/view/BrandLogo.vue'
import {ProjectRoute} from '@/model/Data/ContentRoutes'

@Component({components: {BrandLogo, LanguagePicker, ToolbarTitle, LeftPanel}})
export default class TopBar extends PortalVueBase implements TopBarView {

  toolBarTitle = ''
  currentPage: PortalPageView | null = null
  isLeftPanelVisible = false

  get nextPage(): TopBarNavigationTarget | null {
    const projectNavigation = this.projectNavigation
    if (projectNavigation) return projectNavigation
    if (this.currentPage?.topBarNavigation) return this.currentPage.topBarNavigation
    const pages = [
      {route: this.constants.introduction, title: this.titles.homePage},
      {route: this.constants.solutions, title: this.titles.solutionsPage},
      {route: this.constants.projects, title: this.titles.projectsPage},
      {route: this.constants.experience, title: this.titles.experiencePage},
      {route: this.constants.cv, title: this.titles.cvPage},
      {route: this.constants.contact, title: this.titles.contactPage}
    ]
    const currentIndex = pages.findIndex(page => page.route === this.$route.name)
    const nextPage = currentIndex >= 0 ? pages[currentIndex + 1] || pages[0] : null
    return nextPage ? {to: {name: nextPage.route}, title: nextPage.title} : null
  }

  get projectNavigation(): TopBarNavigationTarget | null {
    if (this.$route.name !== this.constants.project) return null
    const route = this.$route.params.projectRoute as ProjectRoute
    const parent = this.model.projects.findParentByRoute(route)
    return parent
      ? {to: {path: this.constants.projectPath(parent.route)}, title: parent.title}
      : {to: {path: this.constants.projectsPath}, title: this.titles.projectsPage}
  }

  toggleLeftPanelVisibility() {
    this.isLeftPanelVisible = !this.isLeftPanelVisible
  }

  showPage(page: PortalPageView) {
    this.currentPage = page
    this.toolBarTitle = page.pageTitle
  }

}
</script>
