<template>
  <div class="portal-layout">
    <TopBar ref="topBar"/>
    <!--:key="$route.fullPath" is here to reinitialize components when parameters change-->
    <router-view :key="$route.fullPath" ref="page" class="portal-page"/>
    <Footer xs12 />
  </div>
</template>

<style lang="stylus">
.portal-layout
  display flex
  flex 1 0 auto
  flex-direction column

.portal-page
  flex 1 0 auto

@media only screen and (max-width: 320px)
  .container {
    padding: 8px;
  }
</style>

<script lang="ts">
import {Component} from 'vue-property-decorator'
import {PortalVueBase} from '@/view/PortalVueBase'
import TopBar from '@/view/TopBar.vue'
import {PortalPageView, PortalView, TopBarView} from '@/view/View'
import Footer from '@/view/Footer.vue'

@Component({components: {Footer, TopBar}})
export default class Portal extends PortalVueBase implements PortalView {

  get topBar() {
    return this.reference<TopBarView>('topBar')
  }

  get page() {
    return this.reference<PortalPageView>('page')
  }

  mounted() {
    super.mounted()
    this.main.portal = this
    this.topBar.showPage(this.page)
  }

  destroyed() {
    this.main.portal = null
  }
}
</script>
